// Site content. Ported verbatim from the old js/data.js; edit text here.
// media_manifest.json (generated by tools/build_manifest.py) supplies video paths.

export interface Method { key: string; label: string; short: string; ours?: boolean; color: string; card?: boolean; blurb: string }
export interface Scenario { key: string; label: string; desc: string; note?: string }
export interface Task {
  key: string; label: string; dim: string; available: boolean; outcomes: boolean;
  methods: string[];
  methodLabels?: Record<string, string>;   // per-task display names
  methodBlurbs?: Record<string, string>;   // per-task method descriptions
  blurb: string;
  rolloutCaption?: string;
  outcomeCaptions?: { success: string; fail: string };
  absence?: { amrFail?: string; success?: string; fail?: string };
  scenarios: Scenario[];
}
export interface ResultTable {
  title: string; caption: string; cols: string[]; bar: number;
  rows: { c: string[]; ours?: boolean; best?: number[] }[];
}

