// --- The samplers (our method first). `card: false` keeps a method out of the
//     method-card grid while leaving it available to the explorer.
export const METHODS: Method[] = [
  {
    key: 'amr', label: 'CS-Pi', short: 'Ours', ours: true, color: 'var(--accent)',
    blurb: 'Draw an action, project it onto the constraint set, and rather than ' +
           'executing the projection, renoise it to a depth set by how far the ' +
           'action had to move and re-run the unmodified policy from there. ' +
           'Iterating drives the draws to the constraint while each stays in-distribution.'
  },
  {
    key: 'projection', label: 'Projection', short: 'Project + execute', color: '#8a6d4b',
    blurb: 'Move the sampled action to the nearest safe one and execute it. ' +
           'Efficient, but the result is an action the policy would rarely ' +
           'sample, and can be jerky or task-irrelevant.'
  },
  {
    key: 'rejection', label: 'Rejection', short: 'Redraw', color: '#a87a1e',
    blurb: 'Redraw complete actions from the policy until one satisfies the ' +
           'constraint. Every output is in-distribution, but the wait is ' +
           'intractable when feasible actions are rare.'
  },
  {
    key: 'tweedie', label: 'Gradient Guidance', short: 'Guidance', color: '#b8553f',
    blurb: 'Nudge each denoising step along the gradient of a cost, evaluated at ' +
           'a proxy: the average of every clean action the noisy state could still ' +
           'become. When the policy is uncertain between passing left or right of ' +
           'an obstacle, that average can pass straight through it.'
  },
  {
    key: 'trust', label: 'Trust Sampling', short: 'Trust', color: '#5d7d3a',
    blurb: 'Gradient guidance that halts each step at the estimated edge of ' +
           'the policy distribution. It shares our goal but inherits the same ' +
           'proxy bias, at a much larger compute cost.'
  },
  {
    key: 'cbf', label: 'CBF samplers', short: 'SafeDiffuser · SafeFlowMatcher', color: '#5a6472',
    blurb: 'SafeDiffuser and SafeFlowMatcher correct each denoising step with a ' +
           'control-barrier function. They certify feasibility, but the ' +
           'certificate does not constrain likelihood under the policy, and a ' +
           'continuous correction cannot redraw from a surviving policy mode.'
  },
  // --- extra baseline used by the 3D-Orient comparison --------------------
  {
    key: 'unguided', label: 'Unconstrained', short: 'Policy only', color: '#7b8088', card: false,
    blurb: 'The policy alone, with no constraint enforcement.'
  },
  // --- 3D-Orient variants (extra rollouts in viz/orientation_task_gifs) ----
  {
    key: 'amr_dyn', label: 'CS-Pi, cost aligned', short: 'Projection step at the end of the loop', color: 'var(--accent)', card: false,
    blurb: 'Cost aligned: CS-Pi with a projection step at the end of the loop.'
  },
  {
    key: 'tweedie_weak', label: 'Gradient Guidance (α=0.003)', short: 'Guidance, weak', color: '#b8553f', card: false,
    blurb: 'Gradient guidance with a ten times weaker guidance weight (α = 0.003). ' +
           'It keeps more of the reach but rarely achieves the orientation.'
  }
];

